head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[header > P > class]<br/>Header 컴포넌트에 적용하려는 클래스의 이름을 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정할 수 있어야 합니다.",
        "웹표준의 class 속성과 동일한 기능을 제공하며 렌더링 과정에서 웹스퀘어의 기본 클래스가 추가되지 않아야 합니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 렌더된 Header 의 class 속성 / 적용 스타일 확인
scwin.btn_getClassName_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let style1 = window.getComputedStyle(el1);

    wf_body_bottom.getObj("scwin").setReturnValue("target1 적용 스타일 - border : " + style1.border + " , border-radius : " + style1.borderRadius);
    wf_body_bottom.getObj("scwin").setReturnValue("렌더된 class 속성 - target1 : '" + el1.className + "' , target2 : '" + el2.className + "'");
};
